                lengths = np.fromiter((len(v) for v in vals), dtype=np.int64, count=len(vals))
                length_sums = np.bincount(codes, weights=lengths).astype(np.int64)
                score = int(np.sum(length_sums * (counts - 1)))

                if score > best_score or (score == best_score and best_col is not None and col < best_col):
                    best_col = col
                    best_score = score
                    best_codes = codes

            if best_col is None or best_score <= 0:
