            for code in np.unique(best_codes):
                child = rows[best_codes == code]
                stack.append((child, new_prefix, depth + 1))

        # Any groups left after the bounded work budget receive a reliable tail.
        while stack:
            rows, prefix, _ = stack.pop()
            used = set(prefix)
            final = prefix + [col for col in tail_order if col not in used]
            final = self._apply_constraints(final, columns, col_merge, one_way_dep)
            for row in rows:
                orders[int(row)] = final

        return orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """
        Return the best of up to three bounded prefix-cache order constructions.

        Data values are never normalized or rewritten: normalization is used only
        for scoring. Rows are finally lexicographically ordered by their emitted
        strings, and row-specific column ordering metadata is returned alongside
        the positional output dataframe.
        """
        n_rows, n_cols = df.shape
        if n_rows == 0:
            return df.copy(), []
        if n_cols == 0:
            return df.copy(), [[] for _ in range(n_rows)]

        columns = list(df.columns)
        text = self._safe_string_matrix(df)

        original = self._apply_constraints(
            list(range(n_cols)), columns, col_merge, one_way_dep
        )
        frequency = self._apply_constraints(
            self._global_frequency_order(text), columns, col_merge, one_way_dep
        )
        alternate = self._apply_constraints(
            self._alternate_global_order(text), columns, col_merge, one_way_dep
        )

        candidates = []
        for order in (original, frequency, alternate):
            orders = [order] * n_rows
            serialized = self._serialize_orders(text, orders)
            candidates.append((self._trie_score(serialized), orders, serialized, False))

        # Conditional work is intentionally skipped for very large cell counts:
        # two global alternatives remain fast and reliable on wide/huge inputs.
