                depth = min(depth, int(col_stop))
            if row_stop is not None and row_stop > 0:
                depth = min(depth, int(row_stop))

            conditional = self._conditional_orders(
                text, frequency, max(1, depth), col_merge, one_way_dep, columns
            )
            serialized = self._serialize_orders(text, conditional)
            candidates.append((self._trie_score(serialized), conditional, serialized, True))

        # Deterministic ties prefer simpler global candidates.
        best_score, best_orders, best_strings, row_specific = max(
            candidates,
            key=lambda item: (item[0], not item[3])
        )

        row_order = sorted(range(n_rows), key=lambda row: (best_strings[row], row))
        output_orders = [best_orders[row] for row in row_order]

        if not row_specific:
            order = best_orders[0]
            result = df.iloc[row_order, order].copy()
        else:
            # Object dtype is required because different rows may place mixed
            # source dtypes in the same physical output position.
            source = df.to_numpy(dtype=object, copy=False)
            data = np.empty((n_rows, n_cols), dtype=object)
            for out_row, source_row in enumerate(row_order):
                data[out_row, :] = source[source_row, output_orders[out_row]]
            result = pd.DataFrame(data, index=df.index.take(row_order), columns=columns)

        column_orderings = [
            [columns[col] for col in order]
            for order in output_orders
        ]
        return result, column_orderings
