                    total += len(value) * count * (count - 1)
            scores[col] = total

        return sorted(range(n_cols), key=lambda col: (-int(scores[col]), col))

    @staticmethod
    def _apply_constraints(
        order: List[int],
        columns: List,
        col_merge: List[List[str]],
        one_way_dep: List[Tuple[str, str]],
    ) -> List[int]:
        """
        Enforce dependency precedence and contiguous merge-group semantics.

        This function only permutes source positions; it never merges, removes,
        changes, or fabricates dataframe values.
        """
        if not order:
            return order

        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(name, []).append(i)

        def resolve(requested):
            exact = positions.get(requested)
            if exact is not None and len(exact) == 1:
                return exact[0]

            matches = [
                i for i, name in enumerate(columns)
                if str(requested) in str(name)
            ]
            return matches[0] if len(matches) == 1 else None

        result = list(order)

        for left, right in one_way_dep or []:
            a = resolve(left)
            b = resolve(right)
            if a is None or b is None or a == b:
                continue

            ia = result.index(a)
            ib = result.index(b)
            if ia > ib:
                result.pop(ia)
                ib = result.index(b)
                result.insert(ib, a)

        for group in col_merge or []:
            members = [resolve(name) for name in group]
            members = [member for member in members if member is not None]
            if len(members) < 2:
                continue

            insertion = min(result.index(member) for member in members)
            block = [member for member in result if member in members]
            result = [member for member in result if member not in members]
            result[insertion:insertion] = block

        return result

    @staticmethod
    def _column_codes(text: np.ndarray) -> Tuple[List[np.ndarray], np.ndarray]:
        """
        Factorize each serialized column once for reuse by conditional grouping.

        Integer codes avoid repeated object-string factorization at tree nodes.
        """
        n_rows, n_cols = text.shape
        codes = []
        lengths = np.empty((n_rows, n_cols), dtype=np.int32)

        for col in range(n_cols):
            code, _ = pd.factorize(text[:, col], sort=False)
            codes.append(code.astype(np.int64, copy=False))
            lengths[:, col] = np.fromiter(
                (len(value) for value in text[:, col]),
                dtype=np.int32,
                count=n_rows,
            )

        return codes, lengths

    def _conditional_orders(
        self,
        text: np.ndarray,
        tail_order: List[int],
        columns: List,
        col_merge: List[List[str]],
        one_way_dep: List[Tuple[str, str]],
        max_depth: int,
    ) -> List[List[int]]:
        """
        Build bounded row-specific conditional prefix orders.

        Each active group chooses the remaining field with the greatest local
        length-weighted pair repetition, partitions rows by that field, and
        recursively chooses independent suffixes for child groups.
        """
        n_rows, n_cols = text.shape
        if n_rows == 0:
            return []
        if n_cols == 0:
            return [[] for _ in range(n_rows)]

        candidate_limit = min(n_cols, 32)
        candidates = tail_order[:candidate_limit]
        codes, lengths = self._column_codes(text)

        orders = [None] * n_rows
        stack = [(np.arange(n_rows, dtype=np.int64), [], 0)]
        processed = 0
        max_groups = 128

        while stack and processed < max_groups:
            rows, prefix, depth = stack.pop()
            processed += 1
            used = set(prefix)
            available = [col for col in candidates if col not in used]

            if len(rows) <= 1 or depth >= max_depth or not available:
                final = prefix + [col for col in tail_order if col not in used]
                final = self._apply_constraints(
                    final, columns, col_merge, one_way_dep
                )
                for row in rows:
                    orders[int(row)] = final
                continue

            best_col = None
            best_score = 0
            best_inverse = None

            for col in available:
                local_codes = codes[col][rows]
                _, inverse, counts = np.unique(
                    local_codes,
                    return_inverse=True,
                    return_counts=True,
                )

                if counts.max(initial=0) < 2:
                    continue

                local_lengths = lengths[rows, col]
                masses = np.bincount(
                    inverse,
                    weights=local_lengths,
                    minlength=len(counts),
                )
                score = int(np.sum(masses * (counts - 1)))

                if (
                    score > best_score
                    or (
                        score == best_score
                        and best_col is not None
                        and col < best_col
                    )
                ):
                    best_col = col
                    best_score = score
                    best_inverse = inverse

            if best_col is None or best_score <= 0:
                final = prefix + [col for col in tail_order if col not in used]
                final = self._apply_constraints(
                    final, columns, col_merge, one_way_dep
                )
                for row in rows:
                    orders[int(row)] = final
                continue

            next_prefix = prefix + [best_col]
            for code in np.unique(best_inverse):
                child_rows = rows[best_inverse == code]
                stack.append((child_rows, next_prefix, depth + 1))

        while stack:
            rows, prefix, _ = stack.pop()
            used = set(prefix)
            final = prefix + [col for col in tail_order if col not in used]
            final = self._apply_constraints(
                final, columns, col_merge, one_way_dep
            )
            for row in rows:
                orders[int(row)] = final

        return orders

    def _anchor_orders(
        self,
        text: np.ndarray,
        tail_order: List[int],
        columns: List,
        col_merge: List[List[str]],
        one_way_dep: List[Tuple[str, str]],
    ) -> List[List[int]]:
        """
        Build row-specific orders anchored by globally repeated cell values.

        Unlike field-only grouping, this can reuse a common serialized value
        even when it occurs in different source columns in different rows.
        """
        n_rows, n_cols = text.shape
        counts = {}

        for value in text.ravel():
            counts[value] = counts.get(value, 0) + 1

        value_scores = {
            value: len(value) * count * (count - 1)
            for value, count in counts.items()
            if value and count > 1
        }

        orders = []
        for row in range(n_rows):
            best_col = None
            best_score = 0

            for col in range(n_cols):
                score = value_scores.get(text[row, col], 0)
                if score > best_score or (
                    score == best_score
                    and score > 0
                    and (best_col is None or col < best_col)
                ):
                    best_score = score
                    best_col = col

            if best_col is None:
                order = list(tail_order)
            else:
                order = [best_col] + [
                    col for col in tail_order if col != best_col
                ]

            orders.append(
                self._apply_constraints(
                    order, columns, col_merge, one_way_dep
                )
            )

        return orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """
        Return the highest-scoring bounded prefix-cache construction.

        Candidate selection uses actual serialized character-Trie reuse rather
        than adjacent input row similarity or cell-level equality alone.
        """
        n_rows, n_cols = df.shape
        if n_rows == 0:
            return df.copy(), []
        if n_cols == 0:
            return df.copy(), [[] for _ in range(n_rows)]

        columns = list(df.columns)
        text = self._text_matrix(df)

        global_order = self._apply_constraints(
            self._global_frequency_order(text),
            columns,
            col_merge,
            one_way_dep,
        )

        candidates = []

        global_orders = [global_order] * n_rows
        global_strings = self._serialize(text, global_orders)
        candidates.append((
            self._trie_score(global_strings),
            global_orders,
            global_strings,
            False,
        ))

        cell_budget = n_rows * n_cols
        if cell_budget <= 3_000_000 and n_rows > 1 and n_cols > 1:
            depth = min(n_cols, 8)
            if col_stop is not None and col_stop > 0:
                depth = min(depth, int(col_stop))
            if row_stop is not None and row_stop > 0:
                depth = min(depth, int(row_stop))

            conditional_orders = self._conditional_orders(
                text=text,
                tail_order=global_order,
                columns=columns,
                col_merge=col_merge,
                one_way_dep=one_way_dep,
                max_depth=max(1, depth),
            )
            conditional_strings = self._serialize(text, conditional_orders)
            candidates.append((
                self._trie_score(conditional_strings),
                conditional_orders,
                conditional_strings,
                True,
            ))

            anchor_orders = self._anchor_orders(
                text=text,
                tail_order=global_order,
                columns=columns,
                col_merge=col_merge,
                one_way_dep=one_way_dep,
            )
            anchor_strings = self._serialize(text, anchor_orders)
            candidates.append((
                self._trie_score(anchor_strings),
                anchor_orders,
                anchor_strings,
                True,
            ))

        best_score, best_orders, best_strings, row_specific = max(
            candidates,
            key=lambda item: (item[0], not item[3]),
        )

        row_order = sorted(
            range(n_rows),
            key=lambda row: (best_strings[row], row),
        )
        output_orders = [best_orders[row] for row in row_order]

        if not row_specific:
            result = df.iloc[row_order, best_orders[0]].copy()
        else:
            source = df.to_numpy(dtype=object, copy=False)
            output = np.empty((n_rows, n_cols), dtype=object)

            for out_row, source_row in enumerate(row_order):
                output[out_row, :] = source[
                    source_row,
                    output_orders[out_row],
                ]

            result = pd.DataFrame(
                output,
                index=df.index.take(row_order),
                columns=columns,
            )

        column_orderings = [
            [columns[col] for col in order]
            for order in output_orders
        ]
        return result, column_orderings
